public class InnerResponderGatewayManagedEndpointConfigurationFactory(Action<Humidifier.RTBFabric.ResponderGatewayTypes.ManagedEndpointConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.RTBFabric.ResponderGatewayTypes.ManagedEndpointConfiguration>
{

    internal InnerResponderGatewayEksEndpointsConfigurationFactory EksEndpointsConfigurationFactory { get; set; }

    internal InnerResponderGatewayAutoScalingGroupsConfigurationFactory AutoScalingGroupsConfigurationFactory { get; set; }

    protected override Humidifier.RTBFabric.ResponderGatewayTypes.ManagedEndpointConfiguration Create()
    {
        var managedEndpointConfigurationResult = CreateManagedEndpointConfiguration();
        factoryAction?.Invoke(managedEndpointConfigurationResult);

        return managedEndpointConfigurationResult;
    }

    private Humidifier.RTBFabric.ResponderGatewayTypes.ManagedEndpointConfiguration CreateManagedEndpointConfiguration()
    {
        var managedEndpointConfigurationResult = new Humidifier.RTBFabric.ResponderGatewayTypes.ManagedEndpointConfiguration();

        return managedEndpointConfigurationResult;
    }
    public override void CreateChildren(Humidifier.RTBFabric.ResponderGatewayTypes.ManagedEndpointConfiguration result)
    {
        base.CreateChildren(result);

        result.EksEndpointsConfiguration ??= EksEndpointsConfigurationFactory?.Build();
        result.AutoScalingGroupsConfiguration ??= AutoScalingGroupsConfigurationFactory?.Build();
    }

} // End Of Class

